CREATE EXTERNAL DATA SOURCE pg WITH (SOURCE_TYPE = 'PostgreSQL', AUTH_METHOD = 'BASIC', LOGIN = 'u', PASSWORD_SECRET_PATH = 'ext/pw');
CREATE EXTERNAL DATA SOURCE s3 WITH (SOURCE_TYPE = 'ObjectStorage', AUTH_METHOD = 'NONE');
CREATE TABLE t (id Int64 NOT NULL, password_secret_name Utf8, PRIMARY KEY (id));
